    // Wait for the cart count to increment

    const initialCartCount = await page.evaluate(() => document.querySelector('.cart-count').textContent);

    await page.waitForSelector('.cart-count');

    const updatedCartCount = await page.evaluate(() => document.querySelector('.cart-count').textContent);


    // Check if cart count has incremented

