      if (await cartItem.isVisible()) {

        console.log('Product added to cart successfully.');

      } else {

        console.error('Product did not appear in the cart.');

      }

    } else {

      console.error('Cart count did not increment.');

    }

  } else {

    console.error('Add to Cart button is not visible.');

  }


  await browser.close();

})();

